function validate([points]) {
  if (!Array.isArray(points)) return 'points must be an array.';
  if (points.length < 3 || points.length > 100000) return 'points needs 3 to 100000 entries.';
  for (const p of points) {
    if (!Array.isArray(p) || p.length !== 2) return 'Each point is a pair [x, y].';
    if (p.some(c => !Number.isInteger(c) || c < 1 || c > 100000000)) return 'Each coordinate is an integer from 1 to 10^8.';
  }
  return null;
}

