function minimumDistance(points) {
  const n = points.length;
  const sum = points.map(([x, y]) => x + y);
  const diff = points.map(([x, y]) => x - y);

  const extremeIndex = (values, better) => {
    let pick = 0;
    for (let i = 1; i < n; i++) {
      if (better(values[i], values[pick])) {
        pick = i;
      }
    }
    return pick;
  };

  const widestWithout = (skip) => {
    let maxSum = -Infinity;
    let minSum = Infinity;
    let maxDiff = -Infinity;
    let minDiff = Infinity;
    for (let i = 0; i < n; i++) {
      if (i === skip) {
        continue;
      }
      maxSum = Math.max(maxSum, sum[i]);
      minSum = Math.min(minSum, sum[i]);
      maxDiff = Math.max(maxDiff, diff[i]);
      minDiff = Math.min(minDiff, diff[i]);
    }
    return Math.max(maxSum - minSum, maxDiff - minDiff);
  };

  const candidates = [
    extremeIndex(sum, (a, b) => a > b),
    extremeIndex(sum, (a, b) => a < b),
    extremeIndex(diff, (a, b) => a > b),
    extremeIndex(diff, (a, b) => a < b),
  ];

  let best = Infinity;
  for (const skip of candidates) {
    best = Math.min(best, widestWithout(skip));
  }
  return best;
}

