function minimumDistance(points) {
  let best = Infinity;
  for (let removed = 0; removed < points.length; removed++) {
    let widest = 0;
    for (let i = 0; i < points.length; i++) {
      for (let j = i + 1; j < points.length; j++) {
        if (i === removed || j === removed) continue;
        const d = Math.abs(points[i][0] - points[j][0]) + Math.abs(points[i][1] - points[j][1]);
        widest = Math.max(widest, d);
      }
    }
    best = Math.min(best, widest);
  }
  return best;
}

