function generate(rand, size) {
  if (size === 'small') {
    const n = 3 + Math.floor(rand() * 6);
    const span = rand() < 0.3 ? 3 : 12;
    return [Array.from({ length: n }, () => [1 + Math.floor(rand() * span), 1 + Math.floor(rand() * span)])];
  }
  const n = 1500 + Math.floor(rand() * 501);
  const span = rand() < 0.5 ? 100000000 : 1000;
  const points = Array.from({ length: n }, () => [1 + Math.floor(rand() * span), 1 + Math.floor(rand() * span)]);
  if (rand() < 0.5) points[Math.floor(rand() * n)] = [100000000, 100000000];
  return [points];
}
